require_once 'includes/auth.php';
require_once __DIR__.'/../includes/category_images.php';cat_img_ensure($pdo);$edit=(int)($_GET['id']??0);$row=null;if($edit){$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([$edit]);$row=$s->fetch();}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){admin_check_csrf();$id=(int)$_POST['id'];$name=trim($_POST['name']);$slug=trim($_POST['slug']);$emoji=trim($_POST['emoji']??'🛍️');$sort=(int)$_POST['sort_order'];$oldImg=null;if($id){$q=$pdo->prepare('SELECT image FROM categories WHERE id=?');$q->execute([$id]);$oldImg=$q->fetchColumn()?:null;}$img=$oldImg;if(!empty($_POST['remove_image'])){cat_img_delete($oldImg);$img=null;}$up=isset($_FILES['image'])?cat_img_save($_FILES['image']):null;if($up){if($oldImg)cat_img_delete($oldImg);$img=$up;}try{if($id){$s=$pdo->prepare('UPDATE categories SET name=?,slug=?,emoji=?,image=?,sort_order=? WHERE id=?');$s->execute([$name,$slug,$emoji,$img,$sort,$id]);}else{$s=$pdo->prepare('INSERT INTO categories(name,slug,emoji,image,sort_order) VALUES(?,?,?,?,?)');$s->execute([$name,$slug,$emoji,$img,$sort]);}header('Location: categories.php');exit;}catch(Throwable $e){$error='Could not save category. Slug must be unique.';}}if(isset($_GET['delete'])){$s=$pdo->prepare('DELETE FROM categories WHERE id=?');$s->execute([(int)$_GET['delete']]);header('Location: categories.php');exit;}if(isset($_GET['toggle_hide'])){$s=$pdo->prepare('UPDATE categories SET is_hidden = 1 - is_hidden WHERE id=?');$s->execute([(int)$_GET['toggle_hide']]);header('Location: categories.php');exit;}$cats=$pdo->query('SELECT c.*,COUNT(p.id) products FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.name')->fetchAll();
$page_title='Categories';
require 'includes/header.php';
?><div class="row"><div class="card"><h2><?= $row?'Edit':'Add' ?> category</h2><?php if($error):?><div class="notice error"><?=admin_h($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="id" value="<?=intval($row['id']??0)?>"><div class="field"><label>Name</label><input name="name" required value="<?=admin_h($row['name']??'')?>"></div><div class="field"><label>Slug</label><input name="slug" required value="<?=admin_h($row['slug']??'')?>"></div><div class="field"><label>Picture (replaces the emoji)</label><?php if(!empty($row['image'])):?><div style="margin-bottom:8px"><img src="../<?=admin_h($row['image'])?>" alt="" style="width:64px;height:64px;object-fit:cover;border-radius:14px"> <label style="font-weight:400"><input type="checkbox" name="remove_image" value="1"> Remove picture</label></div><?php endif;?><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"></div><div class="field"><label>Emoji (used only if there is no picture)</label><input name="emoji" value="<?=admin_h($row['emoji']??'🛍️')?>"></div><div class="field"><label>Sort order</label><input type="number" name="sort_order" value="<?=intval($row['sort_order']??0)?>"></div><button class="btn">Save</button> <?php if($row):?><a class="btn gray" href="categories.php">Cancel</a><?php endif;?></form></div><div class="card"><h2>All categories</h2><div class="table-wrap"><table class="table"><tr><th>Category</th><th>Products</th><th>Visibility</th><th>Actions</th></tr><?php foreach($cats as $c):?><tr><td><?php if(!empty($c['image'])):?><img src="../<?=admin_h($c['image'])?>" alt="" style="width:32px;height:32px;object-fit:cover;border-radius:9px;vertical-align:middle"><?php else:?><?=admin_h($c['emoji'])?><?php endif;?> <?=admin_h($c['name'])?></td><td><?=intval($c['products'])?></td><td><?php if(!empty($c['is_hidden'])):?><span style="color:red;font-weight:700;">Hidden</span><?php else:?><span style="color:green;font-weight:700;">Visible</span><?php endif;?></td><td><a class="btn" href="categories.php?id=<?=intval($c['id'])?>">Edit</a> <a class="btn" href="categories.php?toggle_hide=<?=intval($c['id'])?>"><?=!empty($c['is_hidden'])?'Show':'Hide'?></a> <a class="btn red" onclick="return confirm('Delete category and its products?')" href="categories.php?delete=<?=intval($c['id'])?>">Delete</a></td></tr><?php endforeach;?></table></div></div></div><?php require 'includes/footer.php';
